-- callboard_service.lua -- Hero's Call Board: transport + parsed state.
--
-- The board is server-authoritative. This module keeps the last payload the server
-- sent (SEND_CALLBOARD_DATA), exposes it to the UI, and sends the three requests
-- (data / accept / claim). Results (SEND_CALLBOARD_RESULT) are forwarded to the UI
-- for toasts; the server always follows a successful accept/claim with a fresh
-- board, so the UI never has to patch state locally.
--
-- Wire (see Comms.h SEND_CALLBOARD_DATA):
--   header: "<dailyIn>,<weeklyIn>,<highestIlvl>,<equippedIlvl>,<cacheProgress>,<cacheRequired>,<cachesOpened>"
--   then one "|" section per quest:
--   "id~category~cadence~done~max~state~ashes~xp~copper~artisan~item~itemCount~orbs~shards~accountWide~featured~title~objectives~description~outleveledAbove~payPct"
--   (since 2026-10-08: description = the quest text of the detail panel; outleveledAbove = the top
--   of the contract's level window when the character is past it, else 0. Since 2026-10-11:
--   payPct = the share of ashes / gold / shards an outleveled contract still pays (x0.8 per level
--   past the top, the figures sent are cut already), 100 inside the window. A 2026-10-08 server sends
--   20 fields and paid nothing past the top; an older one sends 18.)
--   Then (2026-10-11) "~level~minLevel~maxLevel~poiArea~poiX~poiY": the card's level and level window,
--   and the camp on the zone map (WorldMapAreaId + world x / y, 0 = no POI). Absent = older server.
--   cadence 0 daily, 1 weekly, 2 once (a one-shot challenge)
--   Empty body = board disabled server-side.

local addonName, addon = ...

ProjectEbonhold = ProjectEbonhold or {}
local Callboard = {}
ProjectEbonhold.Callboard = Callboard

Callboard.CATEGORY = {
    DUNGEON    = 1,
    RAID       = 2,
    OPEN_WORLD = 3,
    PROFESSION = 4,
    CHALLENGE  = 5,
    OTHER      = 6,
    TORMENT    = 7,
}

-- Board order and labels of the categories (the tabs of the UI; Open World first, his call of
-- 2026-10-08). Challenge (5) is gone: its pool became the Death contracts of the Spirit Healer
-- (modules/contracts).
Callboard.CATEGORIES = {
    { id = 3, name = "Open World", icon = "Interface\\Icons\\INV_Misc_Map_01" },
    { id = 1, name = "Dungeons",   icon = "Interface\\Icons\\INV_Misc_Key_04" },
    { id = 2, name = "Raids",      icon = "Interface\\Icons\\INV_Misc_Head_Dragon_01" },
    { id = 4, name = "Profession", icon = "Interface\\Icons\\INV_Misc_Gear_01" },
    { id = 6, name = "Other",      icon = "Interface\\Icons\\INV_Misc_Note_01" },
    { id = 7, name = "Torment",    icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3" },
}

Callboard.STATE = {
    AVAILABLE = 0,
    ACCEPTED  = 1,
    COMPLETE  = 2,
    EXHAUSTED = 3,
}

Callboard.CADENCE = { DAILY = 0, WEEKLY = 1, ONCE = 2 }

-- The cache object handed out when the bar fills (CallboardMgr::CACHE_ITEM).
Callboard.CACHE_ITEM = 600649

-- Last board received. `receivedAt` is GetTime() at reception so the reset
-- countdowns can tick locally without a new packet.
Callboard.board = nil
Callboard.enabled = true

local listeners = {}

-- UI registers here: fn(eventName, payload). Events: "board", "result".
function Callboard.OnChanged(fn)
    table.insert(listeners, fn)
end

local function fire(event, payload)
    -- No pcall: a fault in a listener is an ordinary Lua error, shown by the client's own
    -- error display, never a chat line.
    for _, fn in ipairs(listeners) do
        fn(event, payload)
    end
end

-- ---------------------------------------------------------------- requests --

function Callboard.Request()
    ProjectEbonhold.sendToServer(ProjectEbonhold.CS.REQUEST_CALLBOARD_DATA, "")
end

function Callboard.Accept(questId)
    if not questId or questId == 0 then return end
    ProjectEbonhold.sendToServer(ProjectEbonhold.CS.REQUEST_CALLBOARD_ACCEPT, tostring(questId))
end

function Callboard.Claim(questId)
    ProjectEbonhold.sendToServer(ProjectEbonhold.CS.REQUEST_CALLBOARD_CLAIM, tostring(questId or 0))
end

function Callboard.ClaimAll()
    Callboard.Claim(0)
end

-- The waystone nearest to a contract's camp (CallboardWaystones.lua, generated by
-- tools/callboard/export_waystone_map.py): { id, name, known } or nil when the contract has none.
-- `known` = the account discovered it (modules/checkpoint's state).
function Callboard.GetWaystone(questId)
    local id = ProjectEbonhold.CallboardWaystones and ProjectEbonhold.CallboardWaystones[questId]
    local service = ProjectEbonhold.CheckpointService
    if not id or not service then return nil end
    for _, node in ipairs(service.GetCheckpoints()) do
        if node.id == id then
            return { id = id, name = node.name, known = node.unlocked }
        end
    end
    return nil
end

-- The world map's travel request: works away from the board, the server keeps its gates
-- (discovered waystone, no vehicle, the travel cast).
function Callboard.Travel(waystoneId)
    if not waystoneId or waystoneId == 0 then return end
    ProjectEbonhold.CheckpointService.UseCheckpoint(waystoneId)
end

-- A contract is an ordinary quest once taken, so abandoning it is the quest log's own
-- abandon; the server rebuilds the card from the log, so the board is asked again as soon
-- as the log has changed.
local abandonPending = false

local function LogIndexOf(questId)
    for i = 1, GetNumQuestLogEntries() do
        local _, _, _, _, isHeader, _, _, _, id = GetQuestLogTitle(i)
        if not isHeader and id == questId then return i end
    end
    return nil
end

function Callboard.Abandon(questId)
    if not questId or questId == 0 then return end
    local index = LogIndexOf(questId)
    if not index then
        -- under a collapsed header: open them all and look again
        ExpandQuestHeader(0)
        index = LogIndexOf(questId)
    end
    if not index then return end
    SelectQuestLogEntry(index)
    SetAbandonQuest()
    AbandonQuest()
    PlaySound("igQuestLogAbandonQuest")
    abandonPending = true
end

local abandonWatcher = CreateFrame("Frame")
abandonWatcher:RegisterEvent("QUEST_LOG_UPDATE")
abandonWatcher:SetScript("OnEvent", function()
    if abandonPending then
        abandonPending = false
        Callboard.Request()
    end
end)

-- ----------------------------------------------------------------- parsing --

local function split(str, sep)
    local out = {}
    local pattern = "([^" .. sep .. "]*)" .. sep
    for part in string.gmatch(str .. sep, pattern) do
        table.insert(out, part)
    end
    return out
end

local function ParseQuest(section)
    local f = split(section, "~")
    if #f < 18 then return nil end
    local q = {
        questId    = tonumber(f[1]) or 0,
        category   = tonumber(f[2]) or 0,
        cadence    = tonumber(f[3]) or 0,
        done       = tonumber(f[4]) or 0,
        max        = tonumber(f[5]) or 1,
        state      = tonumber(f[6]) or 0,
        ashes      = tonumber(f[7]) or 0,
        xp         = tonumber(f[8]) or 0,
        copper     = tonumber(f[9]) or 0,
        artisan    = tonumber(f[10]) or 0,
        item       = tonumber(f[11]) or 0,
        itemCount  = tonumber(f[12]) or 0,
        orbs       = tonumber(f[13]) or 0,
        shards     = tonumber(f[14]) or 0,
        accountWide = (tonumber(f[15]) or 0) == 1,
        featured    = (tonumber(f[16]) or 0) == 1,
        title      = f[17] or "",
        objectives = f[18] or "",
        description = f[19] or "",
        outleveledAbove = tonumber(f[20]) or 0,
        payPct     = tonumber(f[21]),
        -- fields 22-27 (2026-10-11): quest level (-1 = the player's), level window, then the first
        -- quest_poi blob: WorldMapAreaId (0 = none) and its centre in world x / y
        level      = tonumber(f[22]),
        minLevel   = tonumber(f[23]),
        maxLevel   = tonumber(f[24]),
        poiArea    = tonumber(f[25]) or 0,
        poiX       = tonumber(f[26]) or 0,
        poiY       = tonumber(f[27]) or 0,
    }
    -- a server without field 21 paid nothing past the window top (a current one can send 0 too:
    -- 0.8 ^ 73 rounds to 0 % for an 80 holding a level-7 contract - that is not this case)
    q.paysNothing = q.payPct == nil and q.outleveledAbove > 0
    q.payPct = q.payPct or (q.paysNothing and 0 or 100)
    if q.questId == 0 then return nil end
    return q
end

local function ParseBoard(body)
    if not body or body == "" then
        return nil
    end
    local sections = split(body, "|")
    local h = split(sections[1] or "", ",")
    local board = {
        receivedAt     = GetTime(),
        dailyResetIn   = tonumber(h[1]) or 0,
        weeklyResetIn  = tonumber(h[2]) or 0,
        highestIlvl    = tonumber(h[3]) or 0,
        equippedIlvl   = tonumber(h[4]) or 0,
        cacheProgress  = tonumber(h[5]) or 0,
        cacheRequired  = tonumber(h[6]) or 1,
        cachesOpened   = tonumber(h[7]) or 0,
        quests         = {},
        byCategory     = {},
        claimable      = 0,
    }
    for _, cat in ipairs(Callboard.CATEGORIES) do
        board.byCategory[cat.id] = {}
    end
    for i = 2, #sections do
        local q = ParseQuest(sections[i])
        if q then
            table.insert(board.quests, q)
            if board.byCategory[q.category] then
                table.insert(board.byCategory[q.category], q)
            end
            if q.state == Callboard.STATE.COMPLETE then
                board.claimable = board.claimable + 1
            end
        end
    end
    -- Claimable first, then in progress, then available, exhausted last.
    local order = { [2] = 1, [1] = 2, [0] = 3, [3] = 4 }
    for _, list in pairs(board.byCategory) do
        table.sort(list, function(a, b)
            local oa, ob = order[a.state] or 9, order[b.state] or 9
            if oa ~= ob then return oa < ob end
            return a.title < b.title
        end)
    end
    return board
end

-- Seconds left on the daily / weekly reset, ticked from the reception time.
function Callboard.GetResetTimers()
    local b = Callboard.board
    if not b then return 0, 0 end
    local elapsed = GetTime() - (b.receivedAt or GetTime())
    return math.max(0, b.dailyResetIn - elapsed), math.max(0, b.weeklyResetIn - elapsed)
end

function Callboard.GetQuest(questId)
    local b = Callboard.board
    if not b then return nil end
    for _, q in ipairs(b.quests) do
        if q.questId == questId then return q end
    end
    return nil
end

-- --------------------------------------------------------------- handlers --

ProjectEbonhold.onEventReceived(ProjectEbonhold.SS.SEND_CALLBOARD_DATA, function(body)
    if not body or body == "" then
        Callboard.enabled = false
        Callboard.board = nil
    else
        Callboard.enabled = true
        Callboard.board = ParseBoard(body)
    end
    fire("board", Callboard.board)
end)

ProjectEbonhold.onEventReceived(ProjectEbonhold.SS.SEND_CALLBOARD_RESULT, function(body)
    local f = split(body or "", "~")
    local result = { ok = f[1] == "OK", op = f[2] or "" }
    if result.op == "accept" then
        if result.ok then
            result.questId = tonumber(f[3]) or 0
        else
            result.reason  = f[3] or ""
            result.questId = tonumber(f[4]) or 0
        end
    elseif result.op == "claim" then
        if result.ok then
            result.count   = tonumber(f[3]) or 0
            result.ashes   = tonumber(f[4]) or 0
            result.xp      = tonumber(f[5]) or 0
            result.copper  = tonumber(f[6]) or 0
            result.artisan = tonumber(f[7]) or 0
            result.caches  = {}
            for entry in string.gmatch(f[8] or "", "%d+") do
                table.insert(result.caches, tonumber(entry))
            end
            result.items = {}
            for entry, count in string.gmatch(f[9] or "", "(%d+):(%d+)") do
                table.insert(result.items, { entry = tonumber(entry), count = tonumber(count) })
            end
            result.orbs = tonumber(f[10]) or 0
            result.shards = tonumber(f[11]) or 0
            -- claimed past their level window: turned in for nothing
            result.outleveled = tonumber(f[12]) or 0
        else
            result.reason  = f[3] or ""
            result.questId = tonumber(f[4]) or 0
        end
    end
    fire("result", result)
end)
